// ====================== Initialization and Destruction ======================

// Verifies that initializing with a valid load factor retains the exact value.
TEST(Int64ToPtrChainedHashMapTest, InitValidLoadFactor) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 1.0);

    EXPECT_DOUBLE_EQ(map.max_load_factor, 1.0)
        << "Load factor within the [0.5, 2.0] range should remain unmodified.";

    Int64ToPtrChainedHashMapDestroy(&map);
}

// Verifies that a load factor below the minimum threshold is clamped to 0.5.
TEST(Int64ToPtrChainedHashMapTest, InitLoadFactorBelowMin) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 0.1);

    EXPECT_DOUBLE_EQ(map.max_load_factor, 0.5)
        << "Load factor strictly less than 0.5 must be clamped up to 0.5.";

    Int64ToPtrChainedHashMapDestroy(&map);
}

// Verifies that a load factor above the maximum threshold is clamped to 2.0.
TEST(Int64ToPtrChainedHashMapTest, InitLoadFactorAboveMax) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 5.0);

    EXPECT_DOUBLE_EQ(map.max_load_factor, 2.0)
        << "Load factor strictly greater than 2.0 must be clamped down to 2.0.";

    Int64ToPtrChainedHashMapDestroy(&map);
}

// Verifies that load factors exactly at the inclusive bounds are not modified.
TEST(Int64ToPtrChainedHashMapTest, InitLoadFactorExactBounds) {
    Int64ToPtrChainedHashMap lower_bound_map;
    Int64ToPtrChainedHashMapInit(&lower_bound_map, 0.5);
    EXPECT_DOUBLE_EQ(lower_bound_map.max_load_factor, 0.5)
        << "Load factor at the exact lower bound (0.5) should not be altered.";
    Int64ToPtrChainedHashMapDestroy(&lower_bound_map);

    Int64ToPtrChainedHashMap upper_bound_map;
    Int64ToPtrChainedHashMapInit(&upper_bound_map, 2.0);
    EXPECT_DOUBLE_EQ(upper_bound_map.max_load_factor, 2.0)
        << "Load factor at the exact upper bound (2.0) should not be altered.";
    Int64ToPtrChainedHashMapDestroy(&upper_bound_map);
}

// Verifies that destroying a map immediately after initialization does not
// crash or leak.
TEST(Int64ToPtrChainedHashMapTest, DestroyEmptyMap) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 1.0);

    // We rely on memory sanitizers (e.g., ASAN/Valgrind) during the test run
    // to implicitly verify that memory is correctly freed.
    Int64ToPtrChainedHashMapDestroy(&map);

    // We inspect internal fields directly here because the C API lacks
    // `IsEmpty()` or `GetCapacity()` accessors to formally verify a reset
    // state.
    EXPECT_EQ(map.buckets, nullptr)
        << "Bucket array pointer should be reset to null after destruction.";
    EXPECT_EQ(map.size, 0) << "Map size should be zeroed after destruction.";
}

// Verifies that destroying a populated map cleans up all nodes and arrays
// without crashing.
TEST(Int64ToPtrChainedHashMapTest, DestroyPopulatedMap) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 1.0);

    int dummy_val_1 = 42;
    int dummy_val_2 = 84;

    ASSERT_TRUE(Int64ToPtrChainedHashMapSet(&map, 100, &dummy_val_1))
        << "Failed to insert the first element during setup.";
    ASSERT_TRUE(Int64ToPtrChainedHashMapSet(&map, 200, &dummy_val_2))
        << "Failed to insert the second element during setup.";

    Int64ToPtrChainedHashMapDestroy(&map);

    EXPECT_EQ(map.buckets, nullptr)
        << "Bucket array pointer should be reset to null after destruction.";
    EXPECT_EQ(map.size, 0) << "Map size should be reset to 0 upon destruction.";
}

