// Verifies that inserting a value for an already existing key updates the value
// correctly.
TEST(Int64ToPtrChainedHashMapTest, SetUpdateExistingKey) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 1.0);

    int value_a = 100;
    int value_b = 200;
    constexpr int64_t kKey = 42;

    ASSERT_TRUE(Int64ToPtrChainedHashMapSet(&map, kKey, &value_a))
        << "Initial setup of key failed.";

    EXPECT_TRUE(Int64ToPtrChainedHashMapSet(&map, kKey, &value_b))
        << "Updating an existing key should succeed and return true.";

    Int64ToPtrChainedHashMapIterator it =
        Int64ToPtrChainedHashMapGet(&map, kKey);
    ASSERT_TRUE(Int64ToPtrChainedHashMapIteratorIsValid(&it))
        << "Iterator for the updated key must remain valid.";
    EXPECT_EQ(Int64ToPtrChainedHashMapIteratorValue(&it), &value_b)
        << "The mapped value pointer should be updated to point to value_b.";

    // We peek at the internal size field here because the C API lacks a size
    // getter. This ensures the update overwrote the entry rather than creating
    // a duplicate.
    EXPECT_EQ(map.size, 1) << "Updating an existing key must not increase the "
                              "overall size of the map.";

    Int64ToPtrChainedHashMapDestroy(&map);
}

