// Verifies that a key can be successfully re-added with a new value after being
// removed.
TEST(Int64ToPtrChainedHashMapTest, RemoveReadd) {
    Int64ToPtrChainedHashMap map;
    Int64ToPtrChainedHashMapInit(&map, 1.0);

    int value_initial = 10;
    int value_new = 99;
    constexpr int64_t kKey = 42;

    ASSERT_TRUE(Int64ToPtrChainedHashMapSet(&map, kKey, &value_initial))
        << "Setup failed: could not insert initial element.";

    Int64ToPtrChainedHashMapRemove(&map, kKey);

    // We inspect size to ensure the element was genuinely removed before
    // re-adding.
    EXPECT_EQ(map.size, 0) << "Map size should be 0 after removal.";

    EXPECT_TRUE(Int64ToPtrChainedHashMapSet(&map, kKey, &value_new))
        << "Re-adding a previously removed key should succeed.";

    Int64ToPtrChainedHashMapIterator it =
        Int64ToPtrChainedHashMapGet(&map, kKey);
    ASSERT_TRUE(Int64ToPtrChainedHashMapIteratorIsValid(&it))
        << "Iterator must be valid for the re-added key.";
    EXPECT_EQ(Int64ToPtrChainedHashMapIteratorValue(&it), &value_new)
        << "The value retrieved must match the newly inserted value pointer, "
           "not the old one.";

    EXPECT_EQ(map.size, 1) << "Map size should be 1 after the new insertion.";

    Int64ToPtrChainedHashMapDestroy(&map);
}

